        ease: "power2.out",
      },
    );
  }, [loading, stories]);

  useEffect(() => {
    let cancelled = false;

    void (async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await fetch("/api/news/trending");
        const payload = (await response.json()) as {
          stories?: SerializedTrendingNewsStory[];
          error?: string;
